package com.moishow.identity;
import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.time.*;
import static com.moishow.identity.Models.*;import static com.moishow.identity.ApiProblem.require;
@Service @Profile("db")
class HubService {
 final Store db;final JdbcTemplate sql;final FinanceService finance;final tools.jackson.databind.ObjectMapper json;final org.springframework.beans.factory.ObjectProvider<AttachmentAccess> attachments;HubService(Store db,JdbcTemplate sql,FinanceService finance,tools.jackson.databind.ObjectMapper json,org.springframework.beans.factory.ObjectProvider<AttachmentAccess> attachments){this.db=db;this.sql=sql;this.finance=finance;this.json=json;this.attachments=attachments;}
 List<Map<String,Object>> rows(String query,Object...args){return sql.queryForList(query,args).stream().map(CommunityService::view).toList();}
 @Transactional(readOnly=true) public Object discover(Actor a,String query,int offset,int limit){CommunityService.pagination(offset,limit);String q=query==null?"":query.strip();require(q.length()<=100,400,"INVALID_SEARCH");return rows("select id,name,join_mode,version from club where status='ACTIVE' and lower(name) like ? order by name,id limit ? offset ?","%"+q.toLowerCase(Locale.ROOT)+"%",limit,offset);}
 @Transactional(readOnly=true) public Object events(Actor a,UUID club,int offset,int limit){CommunityService.pagination(offset,limit);var c=db.find(Club.class,club);require(c.status.equals("ACTIVE"),403,"CLUB_NOT_ACTIVE");boolean member=db.active(club,a.userId());return rows("select id,club_id,title,kind,public_event,starts_at,ends_at,version from club_event where club_id=? and (? or public_event) order by starts_at,id limit ? offset ?",club,member,limit,offset);}
 @Transactional(readOnly=true) public Object history(Actor a,int offset,int limit){CommunityService.pagination(offset,limit);return rows("select e.id as event_id,e.title,b.status from club_event e join settlement_book b on b.event_id=e.id where e.ends_at<=now() and b.first_registered_at is not null and (e.host_id=? or e.responsible_id=? or exists(select 1 from event_round r join participation p on p.round_id=r.id where r.event_id=e.id and p.user_id=? and p.ever_confirmed)) order by e.starts_at desc,e.id limit ? offset ?",a.userId(),a.userId(),a.userId(),limit,offset);}
 @Transactional(readOnly=true) public Object ownProfile(Actor a){var u=db.find(Account.class,a.userId());require(u.status.equals("ACTIVE"),403,"ACTIVE_ACCOUNT_REQUIRED");return profileView(u);}
 Object profileView(Account u){var result=new LinkedHashMap<String,Object>();result.put("id",u.id);result.put("version",u.version);result.put("nickname",u.nickname);result.put("interests",json.readValue(u.interestsJson,List.class));result.put("bio",u.bio);result.put("avatarFileId",u.avatarFileId);return result;}
 public Object profile(Actor a,HubController.ProfileForm b){
  var u=db.lock(Account.class,a.userId());require(u.status.equals("ACTIVE"),403,"ACTIVE_ACCOUNT_REQUIRED");ClubService.expected(u,b.version());
  require(!(Boolean.TRUE.equals(b.clearAvatar())&&b.avatarFileId()!=null),400,"AVATAR_ACTION_CONFLICT");
  if(b.nickname()!=null)u.nickname=ClubService.text(b.nickname(),50);
  if(b.interests()!=null){require(b.interests().size()<=20,400,"INVALID_INTERESTS");var values=new LinkedHashSet<String>();for(var value:b.interests()){require(value!=null,400,"INVALID_INTERESTS");String tag=value.strip();require(!tag.isEmpty()&&tag.length()<=30,400,"INVALID_INTERESTS");values.add(tag);}u.interestsJson=json.writeValueAsString(values);}
  if(b.bio()!=null){require(b.bio().length()<=300,400,"INVALID_BIO");u.bio=b.bio();}
  if(b.avatarFileId()!=null){var files=attachments.getIfAvailable();require(files!=null,503,"FILE_STORAGE_NOT_CONFIGURED");files.requirePostPhoto(a,b.avatarFileId(),null);u.avatarFileId=b.avatarFileId();}
  if(Boolean.TRUE.equals(b.clearAvatar()))u.avatarFileId=null;
  u.version++;return profileView(u);
 }
 public Object clubNickname(Actor a,UUID id,HubController.ProfileForm b){var club=db.lock(Club.class,id);require(club.status.equals("ACTIVE")&&db.active(id,a.userId()),403,"CLUB_MEMBER_REQUIRED");ClubService.expected(club,b.version());var m=db.member(id,a.userId());m.nickname=ClubService.text(b.nickname(),50);m.version++;club.version++;return Map.of("clubId",id,"nickname",m.nickname,"version",club.version);}
 @Transactional(readOnly=true) public Object home(Actor a,LocalDate date,int offset,int limit){CommunityService.pagination(offset,limit);var tasks=new ArrayList<Map<String,Object>>();var due=new LinkedHashSet<UUID>();for(var q:db.list(FinanceModels.Request.class,"from PaymentRequest where userId=?1 and status='ACTIVE'",a.userId())){var book=db.find(FinanceModels.Book.class,q.bookId);if(finance.target(q,book)>finance.received(q,book))due.add(book.eventId);}for(var id:due){var e=db.find(ClubEvent.class,id);tasks.add(Map.of("eventId",id,"title",e.title,"kind","PAYMENT"));}
  tasks.addAll(rows("select distinct e.id as event_id,e.title,'VERIFY_PAYMENT' as kind from payment_report r join settlement_book b on b.id=r.book_id join club_event e on e.id=b.event_id where e.responsible_id=? and r.status='PENDING'",a.userId()));tasks.addAll(rows("select distinct e.id as event_id,e.title,'REFUND' as kind from finance_refund f join settlement_book b on b.id=f.book_id join club_event e on e.id=b.event_id where f.user_id=? and f.status='SENT'",a.userId()));
  var managed=db.list(ClubEvent.class,"from ClubEvent where responsibleId=?1",a.userId());for(var e:managed){var b=db.one(FinanceModels.Book.class,"from SettlementBook where eventId=?1",e.id);if(b!=null&&b.firstRegisteredAt!=null){boolean refundDue=false;for(var p:finance.participants(e.id))if(finance.position(b,p.userId).refund()>0){refundDue=true;break;}if(refundDue)tasks.add(Map.of("eventId",e.id,"title",e.title,"kind","SEND_REFUND"));}}
  tasks.addAll(rows("select distinct e.id as event_id,e.title,'DISPUTE' as kind from finance_dispute d join settlement_book b on b.id=d.book_id join club_event e on e.id=b.event_id where e.responsible_id=? and d.status in ('OPEN','REVIEWING')",a.userId()));tasks.addAll(rows("select e.id as event_id,e.title,'REGISTER_SETTLEMENT' as kind from club_event e left join settlement_book b on b.event_id=e.id where e.responsible_id=? and e.ends_at<=now() and b.first_registered_at is null",a.userId()));
  for(var h:sql.queryForList("select h.id,h.event_id,h.status,e.title from responsibility_handover h left join club_event e on e.id=h.event_id where h.status<>'COMPLETED' and (h.proposer_id=? or h.candidate_id=?) order by h.created_at,h.id",a.userId(),a.userId())){var task=new LinkedHashMap<String,Object>();task.put("kind","HANDOVER");task.put("title",h.get("title")==null?"적립금 담당 인계":h.get("title"));task.put("eventId",h.get("event_id"));task.put("resourceId",h.get("id"));tasks.add(task);}
  for(var r:sql.queryForList("select r.id,r.event_id,r.kind,r.status,c.name,c.id as club_id from reserve_entry r join reserve_account a on a.id=r.account_id join club c on c.id=a.club_id where r.status not in ('CONFIRMED','COMPLETED','CANCELLED') and (r.created_by=? or a.custodian_id=? or r.recipient_id=?) order by r.created_at,r.id",a.userId(),a.userId(),a.userId())){var task=new LinkedHashMap<String,Object>();task.put("kind","RESERVE");task.put("title",r.get("name")+" 적립금 확인");task.put("eventId",r.get("event_id"));task.put("clubId",r.get("club_id"));task.put("resourceId",r.get("id"));tasks.add(task);}
  var ownerTransfers=rows("select t.id as resource_id,t.club_id,c.name as title,'OWNER_TRANSFER' as kind from club_owner_transfer t join club c on c.id=t.club_id where t.status='PROPOSED' and t.candidate_id=?",a.userId());tasks.addAll(ownerTransfers);
  var all=rows("select e.id,e.title,e.starts_at from club_event e join club c on c.id=e.club_id where c.status='ACTIVE' and (e.host_id=? or exists(select 1 from membership m where m.club_id=e.club_id and m.user_id=? and m.status='ACTIVE' and not m.blacklisted) or exists(select 1 from event_round r join participation p on p.round_id=r.id where r.event_id=e.id and p.user_id=? and p.status='CONFIRMED')) order by e.starts_at,e.id",a.userId(),a.userId(),a.userId());var upcoming=all.stream().filter(e->{Instant start=(Instant)e.get("startsAt");return date==null?!start.isBefore(Instant.now()):start.atZone(ZoneId.of("Asia/Seoul")).toLocalDate().equals(date);}).toList();return Map.of("tasks",tasks,"upcoming",CommunityService.page(upcoming,offset,limit));}
}
